// Who gets the hearts, filled in when the template is added.
const WHO = {{who}};
const PINK = '#FF4F8B';

function ago(minutes) {
  if (minutes < 1) return 'just now';
  if (minutes < 60) return minutes + ' min ago';
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return hours + ' h ago';
  return Math.floor(hours / 24) + ' d ago';
}

function tally(symbol, value, label) {
  return { type: 'hstack', spacing: 4, children: [
    { type: 'symbol', name: symbol, size: 11, weight: 'semibold', color: '#FFFFFFCC' },
    { type: 'text', value: value, size: 15, weight: 'bold', design: 'rounded', color: '#FFFFFF', lineLimit: 1,
      minScale: 0.6 },
    label && { type: 'text', value: label, size: 11, weight: 'medium', color: '#FFFFFFB3', lineLimit: 1,
      minScale: 0.7 },
  ] };
}

function render(ctx) {
  const d = ctx.data;
  const medium = ctx.family === 'medium';
  const them = d.lastIn && (d.lastIn.by.name || WHO);
  const note = d.lastIn
    ? them + ' sent a heart ' + ago(d.lastIn.minutesAgo)
    : 'Send ' + WHO + ' a heart today';

  // The heart is cut out of the disc, so it shows in tinted and clear mode.
  const send = { type: 'button', action: 'send', children: [
    { type: 'symbol', name: 'heart.circle.fill', size: medium ? 56 : 42, color: PINK, accent: true,
      shadow: { color: '#00000066', radius: 6, y: 2 } } ] };

  const tallies = { type: 'hstack', spacing: 10, children: [
    tally('arrow.up.heart.fill', d.sent, medium ? 'sent' : null),
    tally('arrow.down.heart.fill', d.received, medium ? 'received' : null),
  ], shadow: { color: '#00000080', radius: 3 } };

  // The photo fades out toward the bottom instead of sitting under a dark scrim, so the text stays readable in
  // tinted and clear mode, where a scrim would turn into a white sheet and the backdrop shows through instead.
  const photo = { type: 'image', asset: 'photo', crop: medium ? null : [0.2, 0, 0.6, 1],
    mask: { gradient: 'linear', stops: ['#000000FF', '#000000FF', '#00000040'], from: 'top', to: 'bottom' } };

  const noteText = { type: 'text', value: note, size: medium ? 12 : 11, weight: 'medium', color: '#FFFFFFE6',
    lineLimit: medium ? 2 : 3, minScale: 0.7, shadow: { color: '#00000080', radius: 3 } };

  if (medium) {
    return {
      type: 'zstack',
      frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
      widgetBackground: '#1E0D17',
      children: [
        photo,
        { type: 'hstack', align: 'bottom', spacing: 8, padding: 14,
          frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'bottom' },
          children: [
            { type: 'vstack', align: 'leading', spacing: 4, frame: { maxWidth: 'infinity', alignment: 'leading' },
              children: [
                { type: 'text', value: 'Thinking of you', size: 17, weight: 'bold', color: '#FFFFFF', lineLimit: 1,
                  minScale: 0.6, shadow: { color: '#00000080', radius: 3 } },
                noteText,
                tallies,
              ] },
            send,
          ] },
      ],
    };
  }

  return {
    type: 'zstack',
    frame: { maxWidth: 'infinity', maxHeight: 'infinity' },
    widgetBackground: '#1E0D17',
    children: [
      photo,
      { type: 'vstack', align: 'leading', spacing: 0, padding: 12,
        frame: { maxWidth: 'infinity', maxHeight: 'infinity', alignment: 'topLeading' },
        children: [
          tallies,
          { type: 'spacer', minLength: 0 },
          { type: 'hstack', align: 'bottom', spacing: 6, children: [
            { type: 'vstack', frame: { maxWidth: 'infinity', alignment: 'bottomLeading' }, children: [noteText] },
            send ] },
        ] },
    ],
  };
}
